#!/usr/bin/env bash
set -euo pipefail

show_help() {
  cat <<'USAGE'
Zoom Pro — one-shot update bundle

Použití:
  bash zoom-pro-update-all-20260925.sh [cesta_k_repo] [volby]

Příklady:
  cd /cesta/k/zoom-pro && bash ./zoom-pro-update-all-20260925.sh
  bash zoom-pro-update-all-20260925.sh /cesta/k/zoom-pro
  bash zoom-pro-update-all-20260925.sh /cesta/k/zoom-pro --dry-run

Volby:
  --dry-run       rozbalí update a provede kopii souborů, ale bez npm install / DB / buildu
  --skip-install  přeskočí npm install
  --skip-db       přeskočí DB backup a DB migrace
  --help          zobrazí nápovědu
USAGE
}

TARGET=""
DRY_RUN=0
SKIP_INSTALL=0
SKIP_DB=0

for arg in "$@"; do
  case "$arg" in
    --help) show_help; exit 0 ;;
    --dry-run) DRY_RUN=1 ;;
    --skip-install) SKIP_INSTALL=1 ;;
    --skip-db) SKIP_DB=1 ;;
    *)
      if [[ -z "$TARGET" ]]; then TARGET="$arg"; else
        echo "Neznámý argument: $arg" >&2
        exit 1
      fi
      ;;
  esac
done

TARGET="${TARGET:-$PWD}"
TARGET="$(cd "$TARGET" && pwd)"

if [[ ! -f "$TARGET/package.json" || ! -d "$TARGET/apps" ]]; then
  echo "Chyba: cílový adresář nevypadá jako root projektu Zoom Pro: $TARGET" >&2
  exit 1
fi

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="${TARGET%/}-backup-$STAMP"
WORKDIR="$(mktemp -d)"
cleanup() { rm -rf "$WORKDIR"; }
trap cleanup EXIT

load_env_if_present() {
  if [[ -f "$TARGET/.env" ]]; then
    set +u
    set -a
    # shellcheck disable=SC1090
    source "$TARGET/.env" >/dev/null 2>&1 || true
    set +a
    set -u
  fi
}

extract_payload() {
  local marker_line
  marker_line="$(awk '/^__PAYLOAD_BELOW__$/ {print NR + 1; exit 0}' "$0")"
  if [[ -z "$marker_line" ]]; then
    echo "Chyba: payload marker nebyl nalezen." >&2
    exit 1
  fi
  tail -n +"$marker_line" "$0" | base64 -d > "$WORKDIR/payload.tar.gz"
  mkdir -p "$WORKDIR/payload"
  tar -xzf "$WORKDIR/payload.tar.gz" -C "$WORKDIR/payload"
}

copy_tree() {
  local src="$1"
  local dst="$2"
  mkdir -p "$dst"
  tar -cf - -C "$src" . | tar -xf - -C "$dst"
}

echo "════════════════════════════════════════"
echo " Zoom Pro update bundle"
echo " Cíl: $TARGET"
echo " Čas: $STAMP"
echo "════════════════════════════════════════"

echo "[1/7] Záloha souborů do $BACKUP_DIR"
mkdir -p "$BACKUP_DIR"
# file backup without node_modules / build outputs / backups
 tar -cf - \
  --exclude='.git' \
  --exclude='node_modules' \
  --exclude='apps/frontend/node_modules' \
  --exclude='apps/backend/node_modules' \
  --exclude='apps/mobile/node_modules' \
  --exclude='dist' \
  --exclude='apps/frontend/dist' \
  --exclude='apps/mobile/dist' \
  --exclude='backups' \
  --exclude='coverage' \
  --exclude='*.log' \
  --exclude='.DS_Store' \
  -C "$TARGET" . | tar -xf - -C "$BACKUP_DIR"

if [[ "$SKIP_DB" -eq 0 ]]; then
  echo "[2/7] Pokus o DB zálohu"
  load_env_if_present
  if command -v pg_dump >/dev/null 2>&1 && [[ -n "${DATABASE_URL:-}" ]]; then
    mkdir -p "$TARGET/backups"
    if pg_dump "$DATABASE_URL" | gzip > "$TARGET/backups/pre-update-$STAMP.sql.gz"; then
      echo "  ✅ DB záloha: $TARGET/backups/pre-update-$STAMP.sql.gz"
    else
      echo "  ⚠️  DB záloha selhala, pokračuji dál"
    fi
  else
    echo "  ↷ Přeskakuji DB zálohu (není pg_dump nebo DATABASE_URL)"
  fi
else
  echo "[2/7] DB záloha přeskočena (--skip-db)"
fi

echo "[3/7] Rozbaluji update payload"
extract_payload

echo "[4/7] Kopíruji aktualizované soubory"
# payload neobsahuje .env ani node_modules, takže je bezpečné kopírovat vše
copy_tree "$WORKDIR/payload" "$TARGET"

if [[ "$DRY_RUN" -eq 1 ]]; then
  echo "[5/7] Dry-run: npm install přeskočen"
  echo "[6/7] Dry-run: DB migrace přeskočeny"
  echo "[7/7] Dry-run: validace/build přeskočeny"
  echo "✅ Dry-run hotov. Záloha: $BACKUP_DIR"
  exit 0
fi

cd "$TARGET"

if [[ "$SKIP_INSTALL" -eq 0 ]]; then
  echo "[5/7] Instalace závislostí"
  npm install
  if [[ -f apps/mobile/package.json ]]; then
    (cd apps/mobile && npm install)
  fi
else
  echo "[5/7] npm install přeskočen (--skip-install)"
fi

if [[ "$SKIP_DB" -eq 0 ]]; then
  echo "[6/7] Pokus o DB migrace"
  load_env_if_present
  if [[ -n "${DATABASE_URL:-}" ]]; then
    if npm run db:migrate:all; then
      echo "  ✅ DB migrace dokončeny"
    else
      echo "  ⚠️  DB migrace selhaly. Kód je aktualizovaný, ale DB vyžaduje ruční kontrolu." >&2
    fi
  else
    echo "  ↷ Přeskakuji DB migrace (není DATABASE_URL)"
  fi
else
  echo "[6/7] DB migrace přeskočeny (--skip-db)"
fi

echo "[7/7] Validace projektu"
find apps/backend/src scripts -type f \( -name '*.js' -o -name '*.mjs' \) -print0 | xargs -0 -n1 node --check >/dev/null
npm run build -w apps/frontend

echo ""
echo "════════════════════════════════════════"
echo " ✅ Update dokončen"
echo " Záloha souborů: $BACKUP_DIR"
if [[ -f "$TARGET/backups/pre-update-$STAMP.sql.gz" ]]; then
  echo " Záloha DB:      $TARGET/backups/pre-update-$STAMP.sql.gz"
fi
echo " Další krok:     npm run audit:all"
echo "════════════════════════════════════════"
exit 0

